using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;
using System.Text.Json;

namespace MyApp.Evals;

[TestClass]
public class EvalRunner
{
    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_KEY");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }

    private static TracerProvider? SetupTelemetry()
    {
        var otlpEndpoint = Environment.GetEnvironmentVariable("OTEL_EXPORTER_OTLP_ENDPOINT")
            ?? "http://localhost:4317";

        return Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddOtlpExporter(o => o.Endpoint = new Uri(otlpEndpoint))
            .Build();
    }

    [TestMethod]
    public async Task Telemetry_CapturesTraces()
    {
        using var tracer = SetupTelemetry();
        var client = CreateChatClient();

        var scenarios = LoadScenarios();
        foreach (var scenario in scenarios)
        {
            var messages = scenario.Turns
                .Select(t => new ChatMessage(
                    t.Role == "user" ? ChatRole.User : ChatRole.Assistant, t.Content))
                .ToList();

            var response = await client.GetResponseAsync(messages);
            Assert.IsNotNull(response);
            Assert.IsTrue(response.Text.Length > 0,
                $"Scenario '{scenario.Name}' returned empty response");
        }
    }

    [TestMethod]
    public async Task Quality_MeetsThresholds()
    {
        var client = CreateChatClient();
        var judge = CreateChatClient();

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new GroundednessEvaluator(),
        };

        var scenarios = LoadScenarios();
        foreach (var scenario in scenarios)
        {
            var messages = scenario.Turns
                .Select(t => new ChatMessage(
                    t.Role == "user" ? ChatRole.User : ChatRole.Assistant, t.Content))
                .ToList();

            var response = await client.GetResponseAsync(messages);

            var chatHistory = messages.Append(new ChatMessage(ChatRole.Assistant, response.Text)).ToList();

            foreach (var evaluator in evaluators)
            {
                var result = await evaluator.EvaluateAsync(chatHistory, judge);
                foreach (var metric in result)
                {
                    if (metric.Value is NumericMetricValue numericValue)
                    {
                        Assert.IsTrue(numericValue.Value >= 3,
                            $"Scenario '{scenario.Name}' scored {numericValue.Value} on {metric.Key} (min: 3)");
                    }
                }
            }
        }
    }

    [TestMethod]
    public async Task Compare_BaselineVsCandidate()
    {
        var client = CreateChatClient();
        var scenarios = LoadScenarios();

        var results = new List<ScenarioResult>();
        foreach (var scenario in scenarios)
        {
            var messages = scenario.Turns
                .Select(t => new ChatMessage(
                    t.Role == "user" ? ChatRole.User : ChatRole.Assistant, t.Content))
                .ToList();

            var response = await client.GetResponseAsync(messages);

            results.Add(new ScenarioResult
            {
                Name = scenario.Name,
                Response = response.Text,
                TokenCount = response.Text.Length / 4 // approximation
            });
        }

        var outputPath = Path.Combine(FindRepoRoot(), "results", "candidate.json");
        Directory.CreateDirectory(Path.GetDirectoryName(outputPath)!);
        await File.WriteAllTextAsync(outputPath,
            JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true }));

        // If baseline exists, generate comparison
        var baselinePath = Path.Combine(FindRepoRoot(), "results", "baseline.json");
        if (File.Exists(baselinePath))
        {
            var baseline = JsonSerializer.Deserialize<List<ScenarioResult>>(
                await File.ReadAllTextAsync(baselinePath))!;

            var comparisonPath = Path.Combine(FindRepoRoot(), "results", "comparison.md");
            await GenerateComparison(baseline, results, comparisonPath);
        }
    }

    private static async Task GenerateComparison(
        List<ScenarioResult> baseline, List<ScenarioResult> candidate, string outputPath)
    {
        var lines = new List<string>
        {
            "# Evaluation Comparison",
            "",
            "| Scenario | Baseline Length | Candidate Length | Delta |",
            "|----------|---------------|-----------------|-------|"
        };

        foreach (var b in baseline)
        {
            var c = candidate.FirstOrDefault(x => x.Name == b.Name);
            if (c is not null)
            {
                var delta = c.Response.Length - b.Response.Length;
                var sign = delta >= 0 ? "+" : "";
                lines.Add($"| {b.Name} | {b.Response.Length} | {c.Response.Length} | {sign}{delta} |");
            }
        }

        await File.WriteAllTextAsync(outputPath, string.Join(Environment.NewLine, lines));
    }

    private static List<Scenario> LoadScenarios()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Scenarios", "coaching.json");
        var json = File.ReadAllText(path);
        return JsonSerializer.Deserialize<List<Scenario>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;
    }

    private static string FindRepoRoot()
    {
        var dir = AppContext.BaseDirectory;
        while (dir is not null && !File.Exists(Path.Combine(dir, "evaluation.yml")))
            dir = Path.GetDirectoryName(dir);
        return dir ?? AppContext.BaseDirectory;
    }
}

